    number: '01',
    title: 'Fixtures',
    description: 'Open published matches, innings totals, player figures and calculation traces.',
    to: '/fixtures',
    action: 'Browse fixtures',
  },
  {
    number: '02',
    title: 'Competitions',
    description: 'Move from a competition into its seasons, teams and published fixtures.',
    to: '/competitions',
    action: 'Explore competitions',
  },
  {
    number: '03',
    title: 'Players',
    description:
      'Follow a player through named matches with available batting and bowling figures.',
    to: '/participants',
    action: 'Browse players',
  },
];

export function ExploreGateway() {
  return (
    <section className="explore-gateway" aria-labelledby="explore-title">
      <div className="content-boundary">
        <header className="home-section-heading home-section-heading--split">
          <p className="eyebrow">Enter the public record</p>
          <div>
            <h2 id="explore-title">Start with the cricket.</h2>
            <p>No account is required to browse published public records.</p>
          </div>
        </header>
        <ol className="explore-gateway__list">
          {journeys.map((journey) => (
            <li key={journey.title}>
              <span aria-hidden="true">{journey.number}</span>
              <div>
                <h3>{journey.title}</h3>
                <p>{journey.description}</p>
              </div>
              <Link to={journey.to}>
                {journey.action} <span aria-hidden="true">&#8594;</span>
              </Link>
            </li>
          ))}
        </ol>
        <p className="explore-gateway__teams">
          Looking for a side? <Link to="/competitors">Browse teams</Link>.
        </p>
      </div>
    </section>
  );
}

import { lazy, Suspense, useEffect } from 'react';
import { HomeHero } from './HomeHero';

const HomePageContent = lazy(async () => {
  const module = await import('./HomePageContent');
  return { default: module.HomePageContent };
});

export function HomePage() {
  useEffect(() => {
    document.title = "Stat'sTheGame | T20 cricket analytics";
  }, []);

  return (
    <div className="home-page">
      <HomeHero />
      <Suspense fallback={null}>
        <HomePageContent />
      </Suspense>
    </div>
  );
}

import type { AuthChangeEvent, Session } from '@supabase/auth-js';
import { fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import type { ComponentProps } from 'react';
import { MemoryRouter } from 'react-router-dom';
import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { PublicApp } from '../App';
import { AuthProvider } from '../features/auth/AuthProvider';

type AuthClient = ComponentProps<typeof AuthProvider>['client'];
type AuthStateListener = (event: AuthChangeEvent, session: Session | null) => void;

function response(status: number, body: unknown): Response {
  return {
    ok: status >= 200 && status < 300,
    status,
    json: vi.fn().mockResolvedValue(body),
  } as unknown as Response;
}

function collection(data: unknown[], nextCursor: string | null = null, totalPages = 1) {
  return response(200, { data, pagination: { nextCursor, totalPages } });
}

function leaderboard(
  scope: { competitionId: string; competitionName: string; seasonId?: string; season?: string },
  metric: 'most_runs' | 'most_wickets',
  entries: Array<{ rank: number; participantId: string; participantName: string; value: number }>,
) {
  return response(200, {
    data: {
      scope: scope.seasonId ? 'season' : 'competition',
      competitionId: scope.competitionId,
      competitionName: scope.competitionName,
      ...(scope.seasonId ? { seasonId: scope.seasonId, season: scope.season } : {}),
      metric,
      limit: 5,
      qualification: null,
      tieBreakers: ['metricValue', 'participantName', 'participantId'],
      entries,
    },
  });
}

function playerMatch(
  fixtureId: string,
  options: {
    batting?: Record<string, number | null> | null;
    bowling?: Record<string, number | string | null> | null;
    competitionName?: string;
    startDate?: string;
    status?: 'complete' | 'partial';
    teams?: [string, string];
    warnings?: Array<{ code: string; message: string }>;
  } = {},
) {
  const teams = options.teams ?? ['Wanderers', 'Strikers'];
  const competitors = teams.map((name, index) => ({ competitorId: `team-${index + 1}`, name }));
  const competitionName = options.competitionName ?? 'Premier Cricket League';
  const startDate = options.startDate ?? '2026-08-09';

  return {
    fixture: {
      fixtureId,
      competitionId: 'competition-1',
      competitionName,
      seasonId: 'season-1',
      season: '2026',
      seasonLabel: '2026 season',
      competitors,
      matchType: 'T20',
      teamType: 'club',
      gender: 'female',
      ballsPerOver: 6,
      scheduledOvers: 20,
      venue: null,
      toss: null,
      startDate,
      endDate: startDate,
    },
    competitionName,
    competitors,
    competitor: competitors[0],
    role: 'playing_xi',
    statisticsStatus: options.status ?? 'complete',
    statisticsWarnings: options.warnings ?? [],
    batting:
      options.batting === undefined
        ? { runsScored: 42, ballsFaced: 30, fours: 5, sixes: 1, strikeRate: 140 }
        : options.batting,
    bowling:
      options.bowling === undefined
        ? {
            runsConceded: 18,
            wides: 1,
            noBalls: 0,
            legalBallsBowled: 12,
            oversBowled: '2.0',
            wicketsTaken: 2,
            economyRate: 9,
          }
        : options.bowling,
  };
}

/**
 * A participant aggregate response at career scope. The figures are chosen so
 * that none of them equals, or is the sum of, the match-history figures that
 * playerMatch produces, so a page that derived its career totals from the
 * history instead of reading them from this endpoint would show different
 * numbers.
